import{_ as e,o,c as i,ag as a}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"自动更新指南","description":"","frontmatter":{"title":"自动更新指南"},"headers":[],"relativePath":"zh/Modders/Autoupdates.md","filePath":"zh/Modders/Autoupdates.md"}'),l={name:"zh/Modders/Autoupdates.md"};function r(u,t,s,n,p,d){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="自动更新指南" tabindex="-1">自动更新指南 <a class="header-anchor" href="#自动更新指南" aria-label="Permalink to &quot;自动更新指南&quot;">​</a></h1><p>Unciv 包含内置的图像打包和自动更新 uniques 的功能。</p><p>你可以通过向你的仓库添加 GitHub Actions 工作流来自动化这些更新。</p><ul><li>在你的 Github 页面转到 &quot;actions&quot; 标签</li><li>为此仓库推荐 &gt; Simple workflow &gt; &quot;Configure&quot;</li><li>将<a href="https://github.com/yairm210/Unciv-IV-mod/blob/master/.github/workflows/autoupdate.yml" target="_blank" rel="noreferrer">此文件</a>（&quot;copy raw file&quot;）的文本复制到你仓库中的新文件</li><li>在顶部将文件名更改为 &quot;autoupdate.yml&quot;</li><li>&quot;Commit changes&quot;（绿色按钮，右上角） &gt; &quot;Commit changes&quot;</li></ul><p>在每次提交时，以及每天一次，它将：</p><ul><li>尝试压缩 PNG 图像（这是无损的，像素数据保持不变，但文件占用更少空间）</li><li>尝试自动更新已弃用的 uniques</li></ul><p>如果有更改，这将创建一个 PR 到你的仓库 - <a href="https://github.com/yairm210/Unciv-IV-mod/pull/31" target="_blank" rel="noreferrer">这里有一个示例</a> - 你可以选择接受</p><p>如果你看到自动更新不是 100% - 在这种情况下与我联系，我们会解决它 🙂</p><h2 id="错误" tabindex="-1">错误 <a class="header-anchor" href="#错误" aria-label="Permalink to &quot;错误&quot;">​</a></h2><p>如果你收到 <code>remote: Permission to &lt;...&gt;.git denied to github-actions[bot].</code> 你需要：</p><ul><li>打开 Settings &gt; Actions &gt; General</li><li>在 &quot;Workflow permissions&quot; 下选择 &quot;Read and write permissions&quot;、&quot;Allow GitHub Actions to create and approve pull requests&quot;</li></ul><hr><h3 id="⚠️-中文社区特别说明" tabindex="-1">⚠️ 中文社区特别说明 <a class="header-anchor" href="#⚠️-中文社区特别说明" aria-label="Permalink to &quot;⚠️ 中文社区特别说明&quot;">​</a></h3><p>原版 Unciv 项目使用 GitHub Actions 实现模组自动更新。</p><p><strong>Unciv 中文社区采用人工审核更新机制</strong>：</p><ul><li>模组作者通过 QQ 群或 GitHub Issue 提交更新</li><li>社区维护者进行人工审核</li><li>审核通过后由社区统一发布</li></ul><p>这样可以确保：</p><ul><li>翻译质量</li><li>模组兼容性</li><li>中文用户的使用体验</li></ul>',18)])])}const m=e(l,[["render",r]]);export{h as __pageData,m as default};
